import re
from typing import Dict, List, Tuple, Optional

def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    lines = text.splitlines()
    current_section: Optional[str] = None
    sections: Dict[str, Dict[str, str]] = {}
    defaults: Dict[str, str] = {}

    i = 0
    while i < len(lines):
        line = lines[i]
        stripped = line.strip()

        # Skip empty lines and comments
        if not stripped or stripped[0] in ';#':
            i += 1
            continue

        # Section header
        m = re.match(r'^\s*\[([^\]]*)\]\s*$', line)
        if m:
            section_name = m.group(1).strip()
            current_section = section_name
            if section_name == 'DEFAULT':
                # Use defaults dict
                sections.setdefault('DEFAULT', {})
            else:
                sections.setdefault(section_name, {})
            i += 1
            continue

        # Key-value line
        # Check if it's a continuation line (starts with whitespace and follows a key line)
        if line[0] in ' \t' and current_section is not None:
            # Continuation line - handled after parsing key lines
            i += 1
            continue

        if current_section is None:
            raise ValueError("Key-value line before any section header")

        # Parse key-value
        # Find first = or :
        eq_pos = line.find('=')
        colon_pos = line.find(':')

        if eq_pos == -1 and colon_pos == -1:
            raise ValueError(f"Malformed line: {line}")

        # Determine split position
        split_pos = -1
        if eq_pos != -1 and colon_pos != -1:
            split_pos = min(eq_pos, colon_pos)
        elif eq_pos != -1:
            split_pos = eq_pos
        else:
            split_pos = colon_pos

        key = line[:split_pos].strip().lower()
        value_part = line[split_pos + 1:]

        # Handle inline comments and quoted values
        value = parse_value_with_comments(value_part)

        # Handle continuation lines
        full_value = value
        j = i + 1
        while j < len(lines):
            next_line = lines[j]
            next_stripped = next_line.strip()
            # Check if it's a continuation line (starts with whitespace and isn't empty/comment)
            if next_stripped and next_line[0] in ' \t' and next_stripped[0] not in ';#':
                # Check if it looks like a key-value line
                next_eq = next_line.find('=')
                next_colon = next_line.find(':')
                if next_eq != -1 or next_colon != -1:
                    # It's a new key-value line, not continuation
                    break
                full_value += "\n" + next_stripped
                j += 1
            else:
                break

        if current_section == 'DEFAULT':
            defaults[key] = full_value
        else:
            sections[current_section][key] = full_value

        i = j

    # Remove DEFAULT section from output
    if 'DEFAULT' in sections:
        del sections['DEFAULT']

    # Merge DEFAULT values into all other sections without overriding
    for section_name in sections:
        # Start with defaults
        merged = {}
        for k, v in defaults.items():
            merged[k] = v
        # Apply section's own values
        for k, v in sections[section_name].items():
            merged[k] = v
        sections[section_name] = merged

    # Apply interpolation
    # Build a function to resolve references
    def resolve_value(section_name: str, key: str, value: str, _visited: set) -> str:
        # Find all ${...} patterns
        pattern = re.compile(r'\$\{([^}]+)\}')

        def replace_ref(match):
            ref = match.group(1)
            if ':' in ref:
                sec_name, ref_key = ref.split(':', 1)
                if sec_name not in sections and sec_name not in ('DEFAULT',):
                    raise KeyError(f"Section '{sec_name}' not found")
                sec_dict = sections.get(sec_name, {}) if sec_name != 'DEFAULT' else defaults
                if ref_key.lower() not in sec_dict:
                    raise KeyError(f"Key '{ref_key}' not found in section '{sec_name}'")
                return resolve_value(sec_name, ref_key.lower(), sec_dict[ref_key.lower()], _visited | {(sec_name, ref_key.lower())})
            else:
                ref_key = ref.lower()
                if ref_key not in sections[section_name]:
                    raise KeyError(f"Key '{ref}' not found in section '{section_name}'")
                if (section_name, ref_key) in _visited:
                    raise ValueError(f"Circular reference detected: {ref}")
                return resolve_value(section_name, ref_key, sections[section_name][ref_key], _visited | {(section_name, ref_key)})

        return pattern.sub(replace_ref, value)

    # Resolve all interpolations
    for section_name in sections:
        resolved_section = {}
        for key, value in sections[section_name].items():
            resolved_section[key] = resolve_value(section_name, key, value, {(section_name, key)})
        sections[section_name] = resolved_section

    return sections


def parse_value_with_comments(value: str) -> str:
    # Handle quoted values
    stripped = value.strip()
    if stripped.startswith('"') and stripped.endswith('"') and len(stripped) >= 2:
        return stripped[1:-1]

    # Remove inline comments
    # Find ; or # preceded by whitespace
    i = 0
    while i < len(value):
        if value[i] in ';#' and i > 0 and value[i-1] in ' \t':
            return value[:i].strip()
        i += 1

    return value.strip()
