import re

def parse_duration(s: str) -> int:
    if not s or not s.strip():
        raise ValueError("Invalid input")

    structure_pattern = re.compile(r'^\s*((?:\d+[hmsHMS]\s*)+)\s*$', re.IGNORECASE)
    if not structure_pattern.match(s):
        raise ValueError("Invalid format")

    parts = re.findall(r'\d+[hmsHMS]', s, re.IGNORECASE)
    units = []
    nums = []

    for part in parts:
        unit = part[-1].lower()
        num_str = part[:-1]
        num = int(num_str)
        units.append(unit)
        nums.append(num)

    if len(units) != len(set(units)):
        raise ValueError("Duplicate units")

    order_ranks = {'h': 0, 'm': 1, 's': 2}
    prev_rank = -1
    for unit in units:
        curr_rank = order_ranks[unit]
        if curr_rank < prev_rank:
            raise ValueError("Units out of order")
        prev_rank = curr_rank

    total = 0
    for num, unit in zip(nums, units):
        if unit == 'h':
            total += num * 3600
        elif unit == 'm':
            total += num * 60
        elif unit == 's':
            total += num

    return total
```

The provided function first checks for empty or blank input. It then validates the overall structure using a regex that ensures the input is correctly formatted. It extracts each time component and verifies that units are in the correct order without duplicates. Finally, it calculates and returns the total duration in seconds.

