def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    # Sort and remove duplicates
    nums = sorted(set(nums))

    ranges = []
    start = nums[0]
    end = nums[0]

    for i in range(1, len(nums)):
        if nums[i] == end + 1:
            end = nums[i]
        else:
            # Finalize the current run
            if start == end:
                ranges.append(str(start))
            else:
                count = end - start + 1
                if count >= 3:
                    ranges.append(f"{start}..{end}")
                else:
                    # List individually
                    ranges.extend(str(x) for x in range(start, end + 1))
            start = nums[i]
            end = nums[i]

    # Handle the last run
    if start == end:
        ranges.append(str(start))
    else:
        count = end - start + 1
        if count >= 3:
            ranges.append(f"{start}..{end}")
        else:
            ranges.extend(str(x) for x in range(start, end + 1))

    return ",".join(ranges)
